eCount = 32000;  // 32000 stereo frames\n\nAudioInfo info(sampleRate, 2, 32);\nI2SStream i2s;\nI2SConfig cfg;\n\nuint32_t phase = 0;\nconst uint32_t phaseStep =\n    (uint64_t)frequency * 0x100000000ULL / sampleRate;\n\n// Generate TX frames and check RX samples simultaneously\nvoid runI2STest(int &nonZero) {\n\n  nonZero = 0;\n  bool truncated = false;\n\n  int32_t txFrame[2];\n  int32_t rxFrame[2];\n\n  phase = 0;\n\n  for (int i = 0; i < frameCount; i++) {\n\n    // Generate 440 Hz square wave\n    phase += phaseStep;\n\n    int32_t sample =\n        (phase & 0x80000000UL) ? -amplitude : amplitude;\n\n    // Same signal on left and right channels\n    txFrame[0] = sample;\n    txFrame[1] = sample;\n\n    // Write one stereo frame (2 x 32-bit)\n    i2s.write((uint8_t *)txFrame, sizeof(txFrame));\n\n    // Read one stereo frame (2 x 32-bit)\n    size_t n = i2s.readBytes(\n        (uint8_t *)rxFrame,\n        sizeof(rxFrame)\n    );\n\n    if (n == sizeof(rxFrame)) {\n\n      for (int ch = 0; ch < 2; ch++) {\n\n        if (rxFrame[ch] != 0 && rxFrame[ch] != -1) {\n          nonZero++;\n        }\n      }\n\n      // Print first 100 stereo frames\n      if (i < 100) {\n        Serial.printf(\n            "L: %ld  R: %ld\\n",\n            (long)rxFrame[0],\n            (long)rxFrame[1]\n        );\n      }\n      else if (!truncated) {\n        Serial.println("... (truncated)");\n        truncated = true;\n      }\n    }\n  }\n\n  Serial.println();\n}\n\nvoid setup() {\n\n  Serial.begin(115200);\n  while (!Serial);\n\n  AudioLogger::instance().begin(\n      Serial,\n      AudioLogger::Info\n  );\n\n  cfg = i2s.defaultConfig(RXTX_MODE);\n  cfg.copyFrom(info);\n\n  cfg.pin_bck = 8;\n  cfg.pin_ws = 7;\n\n  cfg.pin_data = 44;     // TX\n  cfg.pin_data_rx = 43;  // RX\n\n  cfg.is_master = true;\n\n  i2s.begin(cfg);\n\n  Serial.println("I2S full-duplex test started");\n  Serial.println("Sample rate: 48000 Hz");\n  Serial.println("Channels: 2");\n  Serial.println("Bit depth: 32-bit");\n}\n\nvoid loop() {\n\n  int nonZero = 0;\n\n  Serial.println("First I2S RX test:");\n\n  runI2STest(nonZero);\n\n  Serial.printf(\n      "Valid samples: %d / %d\\n",\n      nonZero,\n      frameCount * 2\n  );\n\n  if (nonZero > frameCount) {\n\n    Serial.println("I2S RX PASS!");\n\n  } else {\n\n    Serial.println(\n        "Valid samples below threshold. Trying again..."\n    );\n\n    nonZero = 0;\n\n    runI2STest(nonZero);\n\n    Serial.printf(\n        "Valid samples: %d / %d\\n",\n        nonZero,\n        frameCount * 2\n    );\n\n    if (nonZero > frameCount) {\n      Serial.println("I2S RX PASS!");\n    } else {\n      Serial.println("I2S RX FAIL!");\n    }\n  }\n\n  Serial.println("Test complete");\n\n  while (true);\n}\n'})}),"\n",(0,s.jsx)(n.h2,{id:"salida-esperada",children:"Salida esperada"}),"\n",(0,s.jsxs)(n.p,{children:["Abre el Monitor Serie a ",(0,s.jsx)(n.strong,{children:"115200 baudios"}),". Un enlace en buen estado se ve as\xed:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-text",children:"I2S full-duplex test started\nSample rate: 48000 Hz\nChannels: 2\nBit depth: 32-bit\nFirst I2S RX test:\nL: -500  R: -500\nL: -500  R: -500\nL: 500  R: 500\n... (truncated)\nValid samples: 63500 / 64000\nI2S RX PASS!\nTest complete\n"})}),"\n",(0,s.jsxs)(n.p,{children:["Los valores exactos en las primeras tramas dependen de lo que capten los micr\xf3fonos. La l\xednea importante es ",(0,s.jsx)(n.code,{children:"I2S RX PASS!"}),"."]}),"\n",(0,s.jsx)(n.h2,{id:"resoluci\xf3n-de-problemas",children:"Resoluci\xf3n de problemas"}),"\n",(0,s.jsx)(n.h3,{id:"i2s-rx-fail",children:(0,s.jsx)(n.code,{children:"I2S RX FAIL!"})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["Confirma que la matriz est\xe1 ejecutando el firmware ",(0,s.jsx)(n.strong,{children:"I2S"}),": la imagen USB no produce datos I2S."]}),"\n",(0,s.jsxs)(n.li,{children:["Comprueba que el paquete de placa sea ",(0,s.jsx)(n.code,{children:"XIAO_